-- NLU's undelivered draft only. Preserve issued invitations, signed agreements, pay and original audit actors.
CREATE TABLE IF NOT EXISTS provider_update_content_revisions (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
 agency_id INT NOT NULL,source_id INT NOT NULL,revision_key VARCHAR(100) NOT NULL,
 automation_actor VARCHAR(120) NOT NULL,snapshot_json JSON NOT NULL,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,applied_at DATETIME NULL,
 UNIQUE KEY uq_provider_update_content_revision(agency_id,source_id,revision_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO provider_update_content_revisions(agency_id,source_id,revision_key,automation_actor,snapshot_json)
SELECT 6,u.id,'nlu-oct-nov-2026-v1','migration:1835_nlu_combined_provider_update',JSON_OBJECT(
 'update',JSON_OBJECT('title',u.title,'subtitle',u.subtitle,'intro_html',u.intro_html),
 'topics',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id',t.id,'topic_key',t.topic_key,'title',t.title,'enabled',t.enabled,'sort_order',t.sort_order,'body_html',t.body_html)) FROM admin_update_topics t WHERE t.update_id=u.id),JSON_ARRAY()),
 'pushes',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id',p.id,'title',p.title,'section_config_json',p.section_config_json,'section_audience_json',p.section_audience_json,'amendment_plan_json',p.amendment_plan_json,'notes',p.notes)) FROM provider_update_pushes p WHERE p.agency_id=6 AND p.attached_admin_update_id=u.id),JSON_ARRAY()))
FROM admin_updates u WHERE u.id=2 AND u.agency_id=6 AND u.status='draft'
 AND NOT EXISTS(SELECT 1 FROM provider_update_pushes p WHERE p.agency_id=6 AND p.attached_admin_update_id=u.id AND (p.status<>'draft' OR p.sent_at IS NOT NULL))
 AND NOT EXISTS(SELECT 1 FROM provider_update_recipients r JOIN provider_update_pushes p ON p.id=r.push_id WHERE p.agency_id=6 AND p.attached_admin_update_id=u.id AND LEFT(r.token,8)<>'preview_')
ON DUPLICATE KEY UPDATE id=provider_update_content_revisions.id;

UPDATE admin_updates u JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL SET u.title='Next Level Up · October and November 2026 Provider Update',u.subtitle='November 2026 release including the undelivered October update',u.intro_html='<p>This combined update includes October’s undelivered update and all NLU changes through November 2026. Review your services, profile, availability, communication choices, handbook changes and your individual compensation amendment. You can save progress and return through your invitation.</p><p>Required review time is tracked while you are actively using the updater. Timed-out and inactive periods are excluded. Use the Technology help option if your recorded time needs review.</p>' WHERE u.agency_id=6 AND u.id=2 AND u.status='draft';

UPDATE provider_update_pushes p JOIN admin_updates u ON u.id=p.attached_admin_update_id AND u.agency_id=p.agency_id JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL
SET p.notes='nlu-oct-nov-2026-v1 Combined October and November 2026 update. No send date is scheduled. Review each employee’s own compensation amendment, including approved services, category, level and individual rates, before releasing it for signature. Complete account-password, six-digit code and personal recovery-email preparation before the individual Google SSO handoff.',p.title=CONCAT(IF(LEFT(p.title,9)='[PREVIEW]','[PREVIEW] ',''),'Next Level Up · October and November 2026 Provider Update'),
 p.section_config_json=JSON_MERGE_PATCH(COALESCE(p.section_config_json,JSON_OBJECT()),CAST('{"services":true,"spanish_intake":false,"client_fall_update":false,"school_availability":false,"amendments":true}' AS JSON)),
 p.amendment_plan_json=CASE WHEN JSON_UNQUOTE(JSON_EXTRACT(p.amendment_plan_json,'$.mode'))='compensation' THEN p.amendment_plan_json ELSE JSON_OBJECT('mode','compensation','title','Individual Compensation Amendment') END
WHERE p.agency_id=6 AND p.status='draft';

UPDATE admin_update_topics t JOIN admin_updates u ON u.id=t.update_id JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL SET t.enabled=0 WHERE u.agency_id=6 AND u.id=2 AND t.topic_key IN ('spanish_intake','school_assignments','client_updates','client_fall_update','compensation','compensation_october','private_virtual_rooms','schoolcarebridge','auricwell');

UPDATE admin_update_topics t JOIN admin_updates u ON u.id=t.update_id JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL SET t.title='Next Level Up · October and November 2026',t.body_html='<p>This combined update includes October’s undelivered update and all NLU changes through November 2026. Review your services, profile, availability, communication choices, handbook changes and your individual compensation amendment. You can save progress and return through your invitation.</p><p>Required review time is tracked while you are actively using the updater. Timed-out and inactive periods are excluded. Use the Technology help option if your recorded time needs review.</p>',t.enabled=1,t.sort_order=0 WHERE u.agency_id=6 AND u.id=2 AND t.topic_key='welcome' AND COALESCE(t.body_html,'') NOT REGEXP '<(video|iframe)|data-training-key';

INSERT INTO admin_update_topics(update_id,topic_key,title,body_html,enabled,icon_key,color,sort_order,is_builtin)
SELECT u.id,'welcome','Next Level Up · October and November 2026','<p>This combined update includes October’s undelivered update and all NLU changes through November 2026. Review your services, profile, availability, communication choices, handbook changes and your individual compensation amendment. You can save progress and return through your invitation.</p><p>Required review time is tracked while you are actively using the updater. Timed-out and inactive periods are excluded. Use the Technology help option if your recorded time needs review.</p>',1,'heart','#0f766e',0,0 FROM admin_updates u JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL WHERE u.agency_id=6 AND u.id=2 AND NOT EXISTS(SELECT 1 FROM admin_update_topics t WHERE t.update_id=u.id AND t.topic_key='welcome');

UPDATE admin_update_topics t JOIN admin_updates u ON u.id=t.update_id JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL SET t.title='Your services · counseling, tutoring or both',t.body_html='<p>Select every service you actually provide in the Services & Tutoring section. If you provide both tutoring and bachelor’s-level counseling, select both. Counseling remains within your verified qualifications and approved facilitator scope; selecting a service does not change your license, compensation category, pay level or service authorization.</p><p>For tutoring, complete subjects and topics, ages, grade levels, your introduction and whether you are accepting students. Review counseling focus areas separately. Your individual amendment must describe the duties and approved pay for each applicable service.</p>',t.enabled=1,t.sort_order=1 WHERE u.agency_id=6 AND u.id=2 AND t.topic_key='services' AND COALESCE(t.body_html,'') NOT REGEXP '<(video|iframe)|data-training-key';

INSERT INTO admin_update_topics(update_id,topic_key,title,body_html,enabled,icon_key,color,sort_order,is_builtin)
SELECT u.id,'services','Your services · counseling, tutoring or both','<p>Select every service you actually provide in the Services & Tutoring section. If you provide both tutoring and bachelor’s-level counseling, select both. Counseling remains within your verified qualifications and approved facilitator scope; selecting a service does not change your license, compensation category, pay level or service authorization.</p><p>For tutoring, complete subjects and topics, ages, grade levels, your introduction and whether you are accepting students. Review counseling focus areas separately. Your individual amendment must describe the duties and approved pay for each applicable service.</p>',1,'client','#0f766e',1,0 FROM admin_updates u JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL WHERE u.agency_id=6 AND u.id=2 AND NOT EXISTS(SELECT 1 FROM admin_update_topics t WHERE t.update_id=u.id AND t.topic_key='services');

UPDATE admin_update_topics t JOIN admin_updates u ON u.id=t.update_id JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL SET t.title='Your profile, languages and NLU website',t.body_html='<p>Review your current photo, introduction, displayed role, credentials, gender and session languages. List another language only when you are proficient enough to conduct sessions in it, and indicate proficiency.</p><p>Deselect the areas you do not serve. Highlight exactly three top choices in each applicable focus category; other areas you have not excluded can still match a client’s search. Your public profile highlights your top choices.</p><p>Review your profile near the end of the update. Open your live page, copy your personal link, or download an NLU-branded QR code. Your saved changes and published availability appear there.</p><p><a href="https://nextleveluplcc.com" target="_blank" rel="noopener">Visit the NLU website ↗</a></p>',t.enabled=1,t.sort_order=2 WHERE u.agency_id=6 AND u.id=2 AND t.topic_key='profile' AND COALESCE(t.body_html,'') NOT REGEXP '<(video|iframe)|data-training-key';

INSERT INTO admin_update_topics(update_id,topic_key,title,body_html,enabled,icon_key,color,sort_order,is_builtin)
SELECT u.id,'profile','Your profile, languages and NLU website','<p>Review your current photo, introduction, displayed role, credentials, gender and session languages. List another language only when you are proficient enough to conduct sessions in it, and indicate proficiency.</p><p>Deselect the areas you do not serve. Highlight exactly three top choices in each applicable focus category; other areas you have not excluded can still match a client’s search. Your public profile highlights your top choices.</p><p>Review your profile near the end of the update. Open your live page, copy your personal link, or download an NLU-branded QR code. Your saved changes and published availability appear there.</p><p><a href="https://nextleveluplcc.com" target="_blank" rel="noopener">Visit the NLU website ↗</a></p>',1,'client','#0f766e',2,0 FROM admin_updates u JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL WHERE u.agency_id=6 AND u.id=2 AND NOT EXISTS(SELECT 1 FROM admin_update_topics t WHERE t.update_id=u.id AND t.topic_key='profile');

UPDATE admin_update_topics t JOIN admin_updates u ON u.id=t.update_id JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL SET t.title='Office bookings, recurring availability and waitlists',t.body_html='<p>First review each office reservation. Confirm it or remove an incorrect reservation to release that room. Existing client appointments remain separate.</p><p>Choose Open, Waitlist or Closed independently for in-person and virtual clients. Closed profiles remain listed. Open profiles with published availability receive priority; a dashboard reminder appears when openings are missing.</p><p>In Set Availability, select reserved office time to offer in-person, virtual or both formats, or keep it private. Click an empty hour to request a room or publish virtual availability. Choose weekly, every other week or every four weeks. Room requests need scheduling review; publishing a virtual opening also sets Virtual to Open. No meetings or one-time openings are created here.</p><p>Keep your typical availability current so clients can understand your schedule when joining your waitlist. Contact hours separately control routine notifications.</p>',t.enabled=1,t.sort_order=3 WHERE u.agency_id=6 AND u.id=2 AND t.topic_key='availability_profiles' AND COALESCE(t.body_html,'') NOT REGEXP '<(video|iframe)|data-training-key';

INSERT INTO admin_update_topics(update_id,topic_key,title,body_html,enabled,icon_key,color,sort_order,is_builtin)
SELECT u.id,'availability_profiles','Office bookings, recurring availability and waitlists','<p>First review each office reservation. Confirm it or remove an incorrect reservation to release that room. Existing client appointments remain separate.</p><p>Choose Open, Waitlist or Closed independently for in-person and virtual clients. Closed profiles remain listed. Open profiles with published availability receive priority; a dashboard reminder appears when openings are missing.</p><p>In Set Availability, select reserved office time to offer in-person, virtual or both formats, or keep it private. Click an empty hour to request a room or publish virtual availability. Choose weekly, every other week or every four weeks. Room requests need scheduling review; publishing a virtual opening also sets Virtual to Open. No meetings or one-time openings are created here.</p><p>Keep your typical availability current so clients can understand your schedule when joining your waitlist. Contact hours separately control routine notifications.</p>',1,'calendar','#0f766e',3,0 FROM admin_updates u JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL WHERE u.agency_id=6 AND u.id=2 AND NOT EXISTS(SELECT 1 FROM admin_update_topics t WHERE t.update_id=u.id AND t.topic_key='availability_profiles');

UPDATE admin_update_topics t JOIN admin_updates u ON u.id=t.update_id JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL SET t.title='Enrollment preferences, notifications and contact hours',t.body_html='<p>Answer each applicable Yes/No choice in the updater and review the Communications Use Agreement. In-app client texting means client SMS reaches your app inbox through the shared agency number. Declining client-text alerts lets the client choose whether to ask support to respond. Personal-phone relay, voice and recording features remain subject to agency setup and availability.</p><p>Choose eligible email/text alerts for appointment replies, kiosk arrivals, messages, meetings and matching Client Exchange opportunities. Appointment replies can be cancellations only, confirmations only or all replies. Arrival texts identify the appointment time; clinical feedback stays in the app and permitted email workflow.</p><p>Client Exchange email and text choices are together. Matching alerts apply only while you are Open for that appointment format; unknown matching information may still qualify. Review the client in the app before requesting them.</p><p>You can change Enrollment preferences in Account settings; Notifications is directly below it. Enrollment controls which eligible text channels can be enabled. Most notification types are app-only. Optional in-app types can also be disabled from an individual notification; required types stay on.</p><p>Choose contact hours that follow saved availability, Anytime, or your own daily windows. For app-only email, choose immediate personal reminders or reminders after 24 business hours. Enabled kiosk arrival emails are urgent and do not wait for that digest.</p><p>NLU uses its own sender, campaign and recorded consent. ITSCO’s voting number and text-assistant enrollment are not NLU enrollment. Features appear only when available for NLU.</p>',t.enabled=1,t.sort_order=4 WHERE u.agency_id=6 AND u.id=2 AND t.topic_key='communications' AND COALESCE(t.body_html,'') NOT REGEXP '<(video|iframe)|data-training-key';

INSERT INTO admin_update_topics(update_id,topic_key,title,body_html,enabled,icon_key,color,sort_order,is_builtin)
SELECT u.id,'communications','Enrollment preferences, notifications and contact hours','<p>Answer each applicable Yes/No choice in the updater and review the Communications Use Agreement. In-app client texting means client SMS reaches your app inbox through the shared agency number. Declining client-text alerts lets the client choose whether to ask support to respond. Personal-phone relay, voice and recording features remain subject to agency setup and availability.</p><p>Choose eligible email/text alerts for appointment replies, kiosk arrivals, messages, meetings and matching Client Exchange opportunities. Appointment replies can be cancellations only, confirmations only or all replies. Arrival texts identify the appointment time; clinical feedback stays in the app and permitted email workflow.</p><p>Client Exchange email and text choices are together. Matching alerts apply only while you are Open for that appointment format; unknown matching information may still qualify. Review the client in the app before requesting them.</p><p>You can change Enrollment preferences in Account settings; Notifications is directly below it. Enrollment controls which eligible text channels can be enabled. Most notification types are app-only. Optional in-app types can also be disabled from an individual notification; required types stay on.</p><p>Choose contact hours that follow saved availability, Anytime, or your own daily windows. For app-only email, choose immediate personal reminders or reminders after 24 business hours. Enabled kiosk arrival emails are urgent and do not wait for that digest.</p><p>NLU uses its own sender, campaign and recorded consent. ITSCO’s voting number and text-assistant enrollment are not NLU enrollment. Features appear only when available for NLU.</p>',1,'chat','#0f766e',4,0 FROM admin_updates u JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL WHERE u.agency_id=6 AND u.id=2 AND NOT EXISTS(SELECT 1 FROM admin_update_topics t WHERE t.update_id=u.id AND t.topic_key='communications');

UPDATE admin_update_topics t JOIN admin_updates u ON u.id=t.update_id JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL SET t.title='Tasks & My Work · know what needs your attention',t.body_html='<p>Tasks shows the work assigned to you. Open each task to see the instructions, due date, attachments, and required action.</p><ul><li><strong>Complete the actual task:</strong> Signing a document, submitting a request, and checking off a task are separate steps. Complete the required action before marking the task as done.</li><li><strong>If you’re blocked:</strong> Use the relevant task to ask for help rather than marking it complete.</li><li><strong>My Work / To-do:</strong> The right panel on the documentation page contains clinical to-dos for providers and their supervisors. These items connect with the Note Aid interface so you can open the relevant documentation workflow. The general Tasks list also contains other assigned work.</li><li><strong>Protect client information:</strong> Keep client details in the appropriate authorized record. Do not copy sensitive information into broad team tasks or announcements.</li></ul><p>A reminder or checked-off task does not confirm that a clinical note, enrollment, signature, or other required step has actually been completed.</p><p>During the current rollout, you may see tasks that do not apply to you or that should already have resolved. Open that task and choose <strong>Report a weird task</strong>. This creates a Technology ticket with the task, assignee, creation time and available source details so the team can investigate. Explain what seems wrong; reporting does not complete or delete the task.</p><p><a target="_blank" rel="noopener noreferrer" href="https://app.nextleveluplcc.com/nlu/tasks">Open Tasks ↗</a> · <a target="_blank" rel="noopener noreferrer" href="https://app.nextleveluplcc.com/nlu/tasks?reportTask=1">Report a weird task ↗</a></p>',t.enabled=1,t.sort_order=5 WHERE u.agency_id=6 AND u.id=2 AND t.topic_key='tasks_my_work' AND COALESCE(t.body_html,'') NOT REGEXP '<(video|iframe)|data-training-key';

INSERT INTO admin_update_topics(update_id,topic_key,title,body_html,enabled,icon_key,color,sort_order,is_builtin)
SELECT u.id,'tasks_my_work','Tasks & My Work · know what needs your attention','<p>Tasks shows the work assigned to you. Open each task to see the instructions, due date, attachments, and required action.</p><ul><li><strong>Complete the actual task:</strong> Signing a document, submitting a request, and checking off a task are separate steps. Complete the required action before marking the task as done.</li><li><strong>If you’re blocked:</strong> Use the relevant task to ask for help rather than marking it complete.</li><li><strong>My Work / To-do:</strong> The right panel on the documentation page contains clinical to-dos for providers and their supervisors. These items connect with the Note Aid interface so you can open the relevant documentation workflow. The general Tasks list also contains other assigned work.</li><li><strong>Protect client information:</strong> Keep client details in the appropriate authorized record. Do not copy sensitive information into broad team tasks or announcements.</li></ul><p>A reminder or checked-off task does not confirm that a clinical note, enrollment, signature, or other required step has actually been completed.</p><p>During the current rollout, you may see tasks that do not apply to you or that should already have resolved. Open that task and choose <strong>Report a weird task</strong>. This creates a Technology ticket with the task, assignee, creation time and available source details so the team can investigate. Explain what seems wrong; reporting does not complete or delete the task.</p><p><a target="_blank" rel="noopener noreferrer" href="https://app.nextleveluplcc.com/nlu/tasks">Open Tasks ↗</a> · <a target="_blank" rel="noopener noreferrer" href="https://app.nextleveluplcc.com/nlu/tasks?reportTask=1">Report a weird task ↗</a></p>',1,'check','#0f766e',5,0 FROM admin_updates u JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL WHERE u.agency_id=6 AND u.id=2 AND NOT EXISTS(SELECT 1 FROM admin_update_topics t WHERE t.update_id=u.id AND t.topic_key='tasks_my_work');

UPDATE admin_update_topics t JOIN admin_updates u ON u.id=t.update_id JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL SET t.title='Notes Workspace · find, write & manage your notes',t.body_html='<p>Use the Notes Workspace as your note-generation tool when Google Workspace and Gemini are retired. It has three main areas, each with a different purpose:</p><ul><li><strong>Right — My Work / To-do:</strong> This shows the sessions and documentation tasks you need to work on. Select an item to open it in the workspace. When available, “Open next in queue” lets you move through your remaining work without searching for each client.</li><li><strong>Center — Writing & Review:</strong> Use this area to create and review notes. Select the appropriate note tool, verify the client, service date, and clinical details, and review all generated content before saving. AI-assisted text must be reviewed by you and does not replace clinical judgment.</li><li><strong>Left — Note Library:</strong> Use the library to search, filter, group, and reopen drafts or saved notes. The Note Library and Work Queue serve different purposes. Deleting a draft does not remove the related item from the Work Queue. If a to-do is no longer needed, remove it from the queue when appropriate.</li></ul><p><strong>Current workflow:</strong> NLU is using the note-generation tools while the full clinical charting and signing process is being rolled out in stages. A saved or reviewed note in this workspace is not automatically a signed TherapyNotes record. Until you receive notice that the workflow has changed, continue copying reviewed notes into TherapyNotes as required.</p><p><a href="https://app.itsco.health/admin/clinical-note-generator">Open Notes Workspace</a></p>',t.enabled=1,t.sort_order=6 WHERE u.agency_id=6 AND u.id=2 AND t.topic_key='notes_workspace' AND COALESCE(t.body_html,'') NOT REGEXP '<(video|iframe)|data-training-key';

INSERT INTO admin_update_topics(update_id,topic_key,title,body_html,enabled,icon_key,color,sort_order,is_builtin)
SELECT u.id,'notes_workspace','Notes Workspace · find, write & manage your notes','<p>Use the Notes Workspace as your note-generation tool when Google Workspace and Gemini are retired. It has three main areas, each with a different purpose:</p><ul><li><strong>Right — My Work / To-do:</strong> This shows the sessions and documentation tasks you need to work on. Select an item to open it in the workspace. When available, “Open next in queue” lets you move through your remaining work without searching for each client.</li><li><strong>Center — Writing & Review:</strong> Use this area to create and review notes. Select the appropriate note tool, verify the client, service date, and clinical details, and review all generated content before saving. AI-assisted text must be reviewed by you and does not replace clinical judgment.</li><li><strong>Left — Note Library:</strong> Use the library to search, filter, group, and reopen drafts or saved notes. The Note Library and Work Queue serve different purposes. Deleting a draft does not remove the related item from the Work Queue. If a to-do is no longer needed, remove it from the queue when appropriate.</li></ul><p><strong>Current workflow:</strong> NLU is using the note-generation tools while the full clinical charting and signing process is being rolled out in stages. A saved or reviewed note in this workspace is not automatically a signed TherapyNotes record. Until you receive notice that the workflow has changed, continue copying reviewed notes into TherapyNotes as required.</p><p><a href="https://app.itsco.health/admin/clinical-note-generator">Open Notes Workspace</a></p>',1,'document','#0f766e',6,0 FROM admin_updates u JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL WHERE u.agency_id=6 AND u.id=2 AND NOT EXISTS(SELECT 1 FROM admin_update_topics t WHERE t.update_id=u.id AND t.topic_key='notes_workspace');

UPDATE admin_update_topics t JOIN admin_updates u ON u.id=t.update_id JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL SET t.title='Clinical consultation and supervision for your role',t.body_html='<p>Attend the consultation, oversight and supervision appropriate to your assigned work. Bachelor’s-level counseling and tutoring do not by themselves require a prelicensure-hour ledger. Only providers identified as prelicensed review tracked licensure hours in this update. Other required oversight and training still apply to the actual assignment.</p>',t.enabled=1,t.sort_order=7 WHERE u.agency_id=6 AND u.id=2 AND t.topic_key='supervision' AND COALESCE(t.body_html,'') NOT REGEXP '<(video|iframe)|data-training-key';

INSERT INTO admin_update_topics(update_id,topic_key,title,body_html,enabled,icon_key,color,sort_order,is_builtin)
SELECT u.id,'supervision','Clinical consultation and supervision for your role','<p>Attend the consultation, oversight and supervision appropriate to your assigned work. Bachelor’s-level counseling and tutoring do not by themselves require a prelicensure-hour ledger. Only providers identified as prelicensed review tracked licensure hours in this update. Other required oversight and training still apply to the actual assignment.</p>',1,'cap','#0f766e',7,0 FROM admin_updates u JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL WHERE u.agency_id=6 AND u.id=2 AND NOT EXISTS(SELECT 1 FROM admin_update_topics t WHERE t.update_id=u.id AND t.topic_key='supervision');

UPDATE admin_update_topics t JOIN admin_updates u ON u.id=t.update_id JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL SET t.title='The new office kiosk · arrival, directions & provider information',t.body_html='<p>The new office kiosk brings client check-in and office information together in one place.</p><ul><li><strong>Client check-in:</strong> Clients select their provider and appointment time, confirm who is checking in, and let the provider know they have arrived. If an appointment is missing, they can use “Message our support team” or ask the office team for help.</li><li><strong>Arrival notifications:</strong> The kiosk records the client’s arrival and sends an in-app notification to the provider. Depending on notification settings, text or email alerts may also be available. Check the app for arrivals.</li><li><strong>Today’s providers:</strong> View provider office hours and room information.</li><li><strong>Office directory:</strong> Find rooms and view the office layout.</li><li><strong>Provider profiles:</strong> View current provider photos and public profile information. Please keep your photo, biography, and focus areas up to date through your Provider Update.</li><li><strong>Programs & events:</strong> View available office programs and events. Program-specific check-in or clock-in/out options will only appear where configured.</li><li><strong>Visit forms & feedback:</strong> Complete assigned visit questionnaires or feedback after check-in. Optional feedback can be skipped and will not prevent check-in. Authorized providers can review saved responses and available trends.</li></ul><p>The kiosk will return to the welcome screen after completion or inactivity. Please finish or clear the screen before leaving it and let staff know if any information appears incorrect.</p><p>The kiosk is intended for arrival and office information only. It is not used to start care or report an emergency.</p><p><a target="_blank" rel="noopener noreferrer" href="https://app.nextleveluplcc.com/nlu/kiosk?mode=office">Open the kiosk entry</a> · Opens in a new window. The entry link will change in the coming weeks to a fixed location. Remind clients to complete check-in as soon as they arrive; they should use the device provided at their office.</p>',t.enabled=1,t.sort_order=8 WHERE u.agency_id=6 AND u.id=2 AND t.topic_key='office_kiosk' AND COALESCE(t.body_html,'') NOT REGEXP '<(video|iframe)|data-training-key';

INSERT INTO admin_update_topics(update_id,topic_key,title,body_html,enabled,icon_key,color,sort_order,is_builtin)
SELECT u.id,'office_kiosk','The new office kiosk · arrival, directions & provider information','<p>The new office kiosk brings client check-in and office information together in one place.</p><ul><li><strong>Client check-in:</strong> Clients select their provider and appointment time, confirm who is checking in, and let the provider know they have arrived. If an appointment is missing, they can use “Message our support team” or ask the office team for help.</li><li><strong>Arrival notifications:</strong> The kiosk records the client’s arrival and sends an in-app notification to the provider. Depending on notification settings, text or email alerts may also be available. Check the app for arrivals.</li><li><strong>Today’s providers:</strong> View provider office hours and room information.</li><li><strong>Office directory:</strong> Find rooms and view the office layout.</li><li><strong>Provider profiles:</strong> View current provider photos and public profile information. Please keep your photo, biography, and focus areas up to date through your Provider Update.</li><li><strong>Programs & events:</strong> View available office programs and events. Program-specific check-in or clock-in/out options will only appear where configured.</li><li><strong>Visit forms & feedback:</strong> Complete assigned visit questionnaires or feedback after check-in. Optional feedback can be skipped and will not prevent check-in. Authorized providers can review saved responses and available trends.</li></ul><p>The kiosk will return to the welcome screen after completion or inactivity. Please finish or clear the screen before leaving it and let staff know if any information appears incorrect.</p><p>The kiosk is intended for arrival and office information only. It is not used to start care or report an emergency.</p><p><a target="_blank" rel="noopener noreferrer" href="https://app.nextleveluplcc.com/nlu/kiosk?mode=office">Open the kiosk entry</a> · Opens in a new window. The entry link will change in the coming weeks to a fixed location. Remind clients to complete check-in as soon as they arrive; they should use the device provided at their office.</p>',1,'spark','#0f766e',8,0 FROM admin_updates u JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL WHERE u.agency_id=6 AND u.id=2 AND NOT EXISTS(SELECT 1 FROM admin_update_topics t WHERE t.update_id=u.id AND t.topic_key='office_kiosk');

UPDATE admin_update_topics t JOIN admin_updates u ON u.id=t.update_id JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL SET t.title='Print your own business cards',t.body_html='<p>You can print your own ITSCO business cards at the office. Preprinted cardstock with the ITSCO website QR code will be available, so you can print your provider information on the other side.</p><h3>How to print</h3><ol><li><strong>Check your profile first.</strong> Open your public provider profile from the Provider Update and make sure your name, credentials, photo, contact information, and profile link are correct.</li><li>Open <strong>Business Cards</strong> from Quick Navigation or the app search, and use the current agency template. Choose the <strong>agency website</strong> QR (the default) or <strong>your provider profile</strong> QR for the back.</li><li><strong>Get the cardstock.</strong> Preprinted business-card cardstock is located in the right drawer of the kitchen desk.</li><li>Use the color Brother printer on the back side of the kitchen desk. The printer can only take one sheet at a time.</li><li>For stock with the agency QR already printed, print <strong>fronts only</strong>. Load the cardstock with the QR-code side facing up so the QR code is readable when you look at it. For your own profile QR, use <strong>blank-backed stock</strong> and print the generated front and back; test the feed direction before printing a batch.</li><li>In the printer settings, set <strong>Print Quality to Great</strong> instead of Good and <strong>Paper Type to Matte Photo Paper</strong>. Click OK.</li><li>Print one sheet first. Check that your information is correct and everything is properly aligned before printing additional cards.</li><li>Once the test sheet looks correct, print additional sheets one at a time.</li></ol><p>The preprinted QR links to the main agency website. Your optional personal profile QR uses the agency logo and links directly to your public provider page. Scan the test card to check its destination.</p><p>Please use the current app-generated template and do not add a private care-texting number or other personal contact information that is not intended for public use.</p><p>If your profile information is incorrect or you have trouble with the template, printer, or alignment, use <strong>Need help</strong> in the Provider Update to submit a <strong>Technology support ticket</strong> before continuing. You can attach screenshots. General ITSCO support: <a href="mailto:support@itsco.health">support@itsco.health</a>.</p>',t.enabled=1,t.sort_order=9 WHERE u.agency_id=6 AND u.id=2 AND t.topic_key='business_cards' AND COALESCE(t.body_html,'') NOT REGEXP '<(video|iframe)|data-training-key';

INSERT INTO admin_update_topics(update_id,topic_key,title,body_html,enabled,icon_key,color,sort_order,is_builtin)
SELECT u.id,'business_cards','Print your own business cards','<p>You can print your own ITSCO business cards at the office. Preprinted cardstock with the ITSCO website QR code will be available, so you can print your provider information on the other side.</p><h3>How to print</h3><ol><li><strong>Check your profile first.</strong> Open your public provider profile from the Provider Update and make sure your name, credentials, photo, contact information, and profile link are correct.</li><li>Open <strong>Business Cards</strong> from Quick Navigation or the app search, and use the current agency template. Choose the <strong>agency website</strong> QR (the default) or <strong>your provider profile</strong> QR for the back.</li><li><strong>Get the cardstock.</strong> Preprinted business-card cardstock is located in the right drawer of the kitchen desk.</li><li>Use the color Brother printer on the back side of the kitchen desk. The printer can only take one sheet at a time.</li><li>For stock with the agency QR already printed, print <strong>fronts only</strong>. Load the cardstock with the QR-code side facing up so the QR code is readable when you look at it. For your own profile QR, use <strong>blank-backed stock</strong> and print the generated front and back; test the feed direction before printing a batch.</li><li>In the printer settings, set <strong>Print Quality to Great</strong> instead of Good and <strong>Paper Type to Matte Photo Paper</strong>. Click OK.</li><li>Print one sheet first. Check that your information is correct and everything is properly aligned before printing additional cards.</li><li>Once the test sheet looks correct, print additional sheets one at a time.</li></ol><p>The preprinted QR links to the main agency website. Your optional personal profile QR uses the agency logo and links directly to your public provider page. Scan the test card to check its destination.</p><p>Please use the current app-generated template and do not add a private care-texting number or other personal contact information that is not intended for public use.</p><p>If your profile information is incorrect or you have trouble with the template, printer, or alignment, use <strong>Need help</strong> in the Provider Update to submit a <strong>Technology support ticket</strong> before continuing. You can attach screenshots. General ITSCO support: <a href="mailto:support@itsco.health">support@itsco.health</a>.</p>',1,'document','#0f766e',9,0 FROM admin_updates u JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL WHERE u.agency_id=6 AND u.id=2 AND NOT EXISTS(SELECT 1 FROM admin_update_topics t WHERE t.update_id=u.id AND t.topic_key='business_cards');

UPDATE admin_update_topics t JOIN admin_updates u ON u.id=t.update_id JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL SET t.title='Prepare your password, six-digit code and temporary Quick View',t.body_html='<p>Set or confirm your app password and six-digit Quick View code, then save both safely in your password manager. They are different credentials. Add an accessible personal recovery email in Contact & Address. Use the sign-in and password-reset links to check your account access; current Google requirements remain in place until your authorized changeover.</p><p>Quick View is temporary while the new app is prepared. The initial app will likely be accessed through AuricWell and will bring your information and notifications together. Keep using the current approved tools until your group receives its confirmed instructions.</p>',t.enabled=1,t.sort_order=10 WHERE u.agency_id=6 AND u.id=2 AND t.topic_key='quick_view' AND COALESCE(t.body_html,'') NOT REGEXP '<(video|iframe)|data-training-key';

INSERT INTO admin_update_topics(update_id,topic_key,title,body_html,enabled,icon_key,color,sort_order,is_builtin)
SELECT u.id,'quick_view','Prepare your password, six-digit code and temporary Quick View','<p>Set or confirm your app password and six-digit Quick View code, then save both safely in your password manager. They are different credentials. Add an accessible personal recovery email in Contact & Address. Use the sign-in and password-reset links to check your account access; current Google requirements remain in place until your authorized changeover.</p><p>Quick View is temporary while the new app is prepared. The initial app will likely be accessed through AuricWell and will bring your information and notifications together. Keep using the current approved tools until your group receives its confirmed instructions.</p>',1,'pin','#0f766e',10,0 FROM admin_updates u JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL WHERE u.agency_id=6 AND u.id=2 AND NOT EXISTS(SELECT 1 FROM admin_update_topics t WHERE t.update_id=u.id AND t.topic_key='quick_view');

UPDATE admin_update_topics t JOIN admin_updates u ON u.id=t.update_id JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL SET t.title='Your NLU handbook · October and November 2026',t.body_html='<p>Review the complete combined October and November changes in Handbook Updates, including the detailed policy text and links to the corresponding NLU handbook sections. The short announcements here are an introduction, not the complete list of changes.</p><p><a href="https://app.nextleveluplcc.com/nlu/workplace-handbook" target="_blank" rel="noopener">Open your NLU Workplace Handbook ↗</a></p><p>Read your own individual compensation amendment in this update. Check each approved service, your category and pay level, rates, indirect/support pay, applicable program terms and effective date before signing. Contact People Operations if a duty or rate is missing or incorrect.</p>',t.enabled=1,t.sort_order=11 WHERE u.agency_id=6 AND u.id=2 AND t.topic_key='handbook' AND COALESCE(t.body_html,'') NOT REGEXP '<(video|iframe)|data-training-key';

INSERT INTO admin_update_topics(update_id,topic_key,title,body_html,enabled,icon_key,color,sort_order,is_builtin)
SELECT u.id,'handbook','Your NLU handbook · October and November 2026','<p>Review the complete combined October and November changes in Handbook Updates, including the detailed policy text and links to the corresponding NLU handbook sections. The short announcements here are an introduction, not the complete list of changes.</p><p><a href="https://app.nextleveluplcc.com/nlu/workplace-handbook" target="_blank" rel="noopener">Open your NLU Workplace Handbook ↗</a></p><p>Read your own individual compensation amendment in this update. Check each approved service, your category and pay level, rates, indirect/support pay, applicable program terms and effective date before signing. Contact People Operations if a duty or rate is missing or incorrect.</p>',1,'document','#0f766e',11,0 FROM admin_updates u JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL WHERE u.agency_id=6 AND u.id=2 AND NOT EXISTS(SELECT 1 FROM admin_update_topics t WHERE t.update_id=u.id AND t.topic_key='handbook');

UPDATE admin_update_topics t JOIN admin_updates u ON u.id=t.update_id JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL SET t.title='The app, Library and account transitions',t.body_html='<p>Use the app’s Tasks, My Work and approved document Library for your assigned work. Prepare your app password, six-digit code and personal recovery email before Google SSO is turned off for you. Continue using your current approved sign-in and documentation system until the confirmed changeover.</p><p>Personal-email notification reminders are temporary. They will be turned off when the new app is ready and notifications are delivered there. Keep your personal email saved for account recovery even after routine notifications move into the app. Texting remains optional.</p>',t.enabled=1,t.sort_order=12 WHERE u.agency_id=6 AND u.id=2 AND t.topic_key='library_transition' AND COALESCE(t.body_html,'') NOT REGEXP '<(video|iframe)|data-training-key';

INSERT INTO admin_update_topics(update_id,topic_key,title,body_html,enabled,icon_key,color,sort_order,is_builtin)
SELECT u.id,'library_transition','The app, Library and account transitions','<p>Use the app’s Tasks, My Work and approved document Library for your assigned work. Prepare your app password, six-digit code and personal recovery email before Google SSO is turned off for you. Continue using your current approved sign-in and documentation system until the confirmed changeover.</p><p>Personal-email notification reminders are temporary. They will be turned off when the new app is ready and notifications are delivered there. Keep your personal email saved for account recovery even after routine notifications move into the app. Texting remains optional.</p>',1,'gear','#0f766e',12,0 FROM admin_updates u JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL WHERE u.agency_id=6 AND u.id=2 AND NOT EXISTS(SELECT 1 FROM admin_update_topics t WHERE t.update_id=u.id AND t.topic_key='library_transition');

INSERT INTO workplace_handbook_digests(agency_id,title,period_label,admin_update_id,status,notes)
SELECT 6,'October and November 2026 NLU Handbook Updates','October and November 2026',u.id,'draft','nlu-oct-nov-2026-v1' FROM admin_updates u JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL WHERE u.agency_id=6 AND u.id=2 AND NOT EXISTS(SELECT 1 FROM workplace_handbook_digests d WHERE d.agency_id=6 AND d.admin_update_id=u.id AND d.notes='nlu-oct-nov-2026-v1');

INSERT INTO workplace_handbook_digest_entries(digest_id,agency_id,sort_order,subject,rationale,changed_content,handbook_section_slug,change_kind,previous_content)
SELECT target.id,6,prior.sort_order,prior.subject,prior.rationale,prior.changed_content,prior.handbook_section_slug,prior.change_kind,prior.previous_content
FROM workplace_handbook_digests target JOIN admin_updates u ON u.id=target.admin_update_id JOIN provider_update_content_revisions revision ON revision.agency_id=6 AND revision.source_id=u.id AND revision.revision_key='nlu-oct-nov-2026-v1' AND revision.applied_at IS NULL
JOIN (SELECT e.*,ROW_NUMBER() OVER(PARTITION BY e.subject ORDER BY d.id DESC,e.id DESC) AS latest FROM workplace_handbook_digest_entries e JOIN workplace_handbook_digests d ON d.id=e.digest_id WHERE d.agency_id=6 AND d.admin_update_id=2 AND COALESCE(d.notes,'')<>'nlu-oct-nov-2026-v1') prior ON prior.latest=1
WHERE target.agency_id=6 AND target.notes='nlu-oct-nov-2026-v1' AND NOT EXISTS(SELECT 1 FROM workplace_handbook_digest_entries existing WHERE existing.digest_id=target.id AND existing.subject=prior.subject);

UPDATE provider_update_content_revisions SET applied_at=UTC_TIMESTAMP() WHERE agency_id=6 AND source_id=2 AND revision_key='nlu-oct-nov-2026-v1' AND applied_at IS NULL;
